sc_cat_item_producer.post_insert_script:
(function executeProducerScript(current, producer, cat_item) {
    // Create 4 initial Case Document child records linked to this case
    var documentTypes = [
        'passport',
        'degree_certificate',
        'power_of_attorney',
        'job_contract'
    ];

    for (var i = 0; i < documentTypes.length; i++) {
        var doc = new GlideRecord('x_2023506_german_1_case_doc');
        doc.initialize();
        doc.u_case = current.sys_id;
        doc.u_document_name = documentTypes[i];
        doc.u_status = 'pending';
        doc.insert();
    }
})(current, producer, cat_item);

sc_cat_item_producer.script:
(function executeProducerScript(current, producer) {
    // Set default state to Open (1)
    current.state = 1;
    // Set priority to Moderate (3)
    current.priority = 3;
    // Set fee defaults
    current.u_fee_amount = 411.00;
    current.u_fee_status = 'unpaid';
    // Build short_description from candidate name
    current.short_description = 'Fast-Track Case: ' + producer.candidate_name;
})(current, producer);
